class PurchaseDesk:
    def __init__(self, db):
        self.db = Path(db)
        if not self.db.is_file():
            raise ValueError('Primero carga el paquete documental en la base indicada.')
        self.store = CompanyDataStore(self.db)
        with sqlite3.connect(self.db) as c:
            c.execute('SELECT dataset_id FROM documentary_company_snapshot LIMIT 1')
            c.execute('''CREATE TABLE IF NOT EXISTS manual_purchase_proposal (
                proposal_id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL,
                created_at TEXT NOT NULL, payload TEXT NOT NULL,
                FOREIGN KEY(dataset_id) REFERENCES documentary_company_snapshot(dataset_id))''')

    def review(self, dataset, proposal_id):
        state = self.state(dataset)
        proposal = next((p for p in state['purchases'] if p['proposal_id'] == proposal_id), None)
        if proposal is None:
            raise ValueError('Propuesta no encontrada en la versión seleccionada.')
        saved_context = proposal.get('documentary_context_at_save')
        current_context = state['documentary_context']
        if saved_context is not None and saved_context != current_context:
            raise ValueError('Los datos documentales han cambiado respecto a la propuesta guardada. Prepara una nueva propuesta con la versión revisada.')
        article = proposal['article_id']
        report = review_proposal(proposal, state['info'], state['history'].get(article, []),
                                 state['inventory'].get(article), state['planning'].get(article))
        report['financial_context'] = financial_context(self.store, dataset, state['info'])
        report['payment_matching'] = payment_matching(proposal, report['financial_context'])
        from eios.company_payment_associations import read_associations
        report['payment_associations'] = read_associations(self.db,report)
        report['finance_execution'] = execute_documentary_finance(self.db,proposal,report['financial_context'],report['payment_associations'])
        from eios.company_payment_review import read_documentary_review
        report['payment_documentary_review'] = read_documentary_review(self.db,report)
        from eios.company_required_calendar import read_required_calendar
        report['required_calendar_coverage'] = read_required_calendar(self.db,report)
        from eios.company_reviewer_designation import read_reviewer_designation
        report['reviewer_designation'] = read_reviewer_designation(self.db,report)
        from eios.company_finance_quality import read_quality_preparation
        report['finance_quality_preparation'] = read_quality_preparation(self.db,report)
        from eios.company_treasury_support import read_treasury_support
        report['treasury_documentary_support'] = read_treasury_support(self.db,report)
        from eios.company_treasury_context import read_treasury_context
        report['treasury_contextual_assessment'] = read_treasury_context(self.db,report)
        report['version'] = 'COMPANY-CONTEXT-REVIEW-15'
        report['finance']['message'] = report['finance_execution']['message']
        from hashlib import sha256
        report.pop('review_id', None)
        report['review_id'] = sha256(json.dumps(report,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
        report['reviewed_at'] = datetime.now(timezone.utc).isoformat()
        with sqlite3.connect(self.db) as c:
            c.execute('PRAGMA foreign_keys=ON')
            c.execute('BEGIN IMMEDIATE')
            if capture_context(c, dataset) != current_context:
                raise ValueError('Los datos documentales han cambiado durante la revisión.')
            c.execute('''CREATE TABLE IF NOT EXISTS manual_purchase_context_review (
                review_id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL, proposal_id TEXT NOT NULL,
                payload TEXT NOT NULL, FOREIGN KEY(proposal_id) REFERENCES manual_purchase_proposal(proposal_id))''')
            c.execute('INSERT OR IGNORE INTO manual_purchase_context_review VALUES(?,?,?,?)',
                      (report['review_id'], dataset, proposal_id, json.dumps(report)))
            return json.loads(c.execute('SELECT payload FROM manual_purchase_context_review WHERE review_id=?',
                                        (report['review_id'],)).fetchone()[0])


    def _saved_review(self, dataset, proposal_id, review_id):
        """Read one exact saved review without loading current company data."""
        with sqlite3.connect(self.db) as c:
            if not c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='manual_purchase_context_review'").fetchone():
                raise ValueError('Primero revisa la propuesta para generar el informe.')
            row = c.execute('SELECT payload FROM manual_purchase_context_review WHERE dataset_id=? AND proposal_id=? AND review_id=?',
                            (dataset, proposal_id, review_id)).fetchone()
        if row is None:
            raise ValueError('Revisión no encontrada en la propuesta y versión seleccionadas.')
        report = json.loads(row[0])
        if (report.get('dataset_id'), report.get('proposal_id'), report.get('review_id')) != (dataset, proposal_id, review_id):
            raise ValueError('La identidad de la revisión guardada no coincide.')
        return report

    def declare_payment_association(self, data):
        from eios.company_payment_associations import save_association
        report = self._saved_review(str(data['dataset_id']), str(data['proposal_id']), str(data['review_id']))
        return save_association(self.db, report, data)

    def captured_payment_document(self, dataset, proposal_id, review_id, document_ref):
        from eios.company_payment_documents import captured_document
        return captured_document(self.db, self._saved_review(dataset,proposal_id,review_id), document_ref)

    def record_payment_documentary_review(self, data):
        from eios.company_payment_review import save_documentary_review
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_documentary_review(self.db,report,data)

    def record_required_calendar(self, data):
        from eios.company_required_calendar import save_required_calendar
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_required_calendar(self.db,report,data)

    def prepare_finance_quality(self, data):
        from eios.company_finance_quality import save_quality_preparation
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_quality_preparation(self.db,report,data)

    def record_treasury_support(self, data):
        from eios.company_treasury_support import save_treasury_support
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_treasury_support(self.db,report,data)

    def record_treasury_observation(self, data):
        from eios.company_treasury_support import save_treasury_observation
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_treasury_observation(self.db,report,data)

    def record_treasury_context(self, data):
        from eios.company_treasury_context import save_treasury_context
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_treasury_context(self.db,report,data)

    def record_reviewer_designation(self, data):
        from eios.company_reviewer_designation import save_reviewer_designation
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_reviewer_designation(self.db,report,data)

    def record_designation_observation(self, data):
        from eios.company_reviewer_designation import save_designation_observation
        report=self._saved_review(str(data['dataset_id']),str(data['proposal_id']),str(data['review_id']))
        return save_designation_observation(self.db,report,data)

    def printable_report(self, dataset, proposal_id, review_id):
        from eios.company_proposal_report import render_report
        return render_report(self._saved_review(dataset, proposal_id, review_id))

    def commercial_draft(self, dataset, proposal_id, review_id):
        from eios.company_commercial_draft import commercial_draft
        return commercial_draft(self._saved_review(dataset, proposal_id, review_id))

    def sales_offer(self, data, *, persist=True):
        from eios.company_sales_proposals import save_offer
        from eios.company_sales_workflow import customer_credit
        state=self.sales_state(str(data['dataset_id']))
        state['sales_customer_credit']=customer_credit(self.store,str(data['dataset_id']),data.get('customer_id'),state['info']['as_of_date'])
        return save_offer(self.db,state,data,persist=persist)

    def sales_cash_plan(self, data, *, save=False):
        from eios.company_sales_cash_plan import read_plan, save_plan
        state=self.sales_state(str(data['dataset_id']))
        return save_plan(self.db,state,data) if save else read_plan(self.db,state,str(data['proposal_id']))

    def sales_state(self, dataset):
        from eios.company_parameters import read_parameters
        state=self.state(dataset)
        state['sales_parameters']=read_parameters(self.db,self.store,dataset)['current']
        state['sales_financial_context']=financial_context(self.store,dataset,state['info'])
        return state

    def sales_orientation(self, data):
        from eios.company_sales_proposals import orientation
        state=self.sales_state(str(data['dataset_id']))
        if data.get('customer_id') and data.get('customer_id') not in {c['customer_id'] for c in state['customers']}:
            raise ValueError('Selecciona un cliente de esta versión.')
        article=next((a for a in state['articles'] if a['article_id']==data.get('article_id')),None)
        if article is None:
            raise ValueError('Selecciona un artículo de esta versión.')
        from eios.company_sales_negotiation import price_reference
        basis=orientation(state,data['customer_id'],article)
        from eios.company_sales_workflow import customer_credit
        price=price_reference(basis,state['sales_parameters'],article,data.get('offer_date'))
        previous={Decimal(s['net_unit_price']) for s in basis['latest_sales']}
        stale_sales=(basis.get('sales_history_status') or {}).get('status')=='STALE'
        default=str(next(iter(previous))) if len(previous)==1 else price['recommended_unit_price'] if not previous else None
        if stale_sales:default=None
        from eios.company_sales_tariffs import candidates
        with sqlite3.connect(self.db) as c:tariffs=candidates(c,state['documentary_context'],article)
        return dict(basis,tariff_candidates=tariffs,article=article,price_reference=price,default_unit_price=default,
            default_price_source='STALE_RECEIVED_SALES_HISTORY' if stale_sales else 'LAST_CUSTOMER_SALE' if len(previous)==1 else 'RECOMMENDED_ORIGIN' if not previous else 'AMBIGUOUS_HISTORY',
            customer_credit=customer_credit(self.store,str(data['dataset_id']),data.get('customer_id'),state['info']['as_of_date']))

    def state(self, dataset):
        info = self.store.describe(dataset)
        history={a['data']['article_id']:purchase_history(self.store,dataset,a['data'],info['as_of_date']) for a in self.store.records(dataset,'article')}
        with sqlite3.connect(self.db) as c:
            c.execute('BEGIN')
            documentary_context = capture_context(c, dataset)
            proposals = [json.loads(r[0]) for r in c.execute(
                'SELECT payload FROM manual_purchase_proposal WHERE dataset_id=? ORDER BY created_at DESC', (dataset,))]
        from eios.company_sales_proposals import offers
        from eios.company_sales_links import apply_links
        from eios.company_sales_tariffs import apply_tariffs
        from eios.company_commercial_catalogue import apply_catalogue
        with sqlite3.connect(self.db) as c:
            articles,suppliers,commercial_catalogue=apply_catalogue(c,dataset,[r['data'] for r in self.store.records(dataset,'article')],[r['data'] for r in self.store.records(dataset,'supplier')])
        articles=apply_tariffs(self.db,self.store,dataset,articles)
        from eios.company_selected_purchases import apply_history
        with sqlite3.connect(self.db) as c:history,selected_purchase_history,received_purchase_lines=apply_history(c,dataset,history)
        for a in articles:history.setdefault(a['article_id'],[])
        inventory=read_inventory(self.db,dataset)
        from eios.company_selected_inventory import inventory_status
        with sqlite3.connect(self.db) as c:selected_inventory=inventory_status(c,dataset)
        minimums=read_minimums(self.db,info['company']['company_id'],articles,inventory,history)
        metrics=stock_metrics(self.store,dataset,info['as_of_date'])
        parties={s['supplier_id']:s for s in suppliers}
        for a in articles:
            if a['article_id'] not in metrics:
                metrics[a['article_id']]=dict(suppliers=[dict(supplier_id=a['supplier_id'],name=parties[a['supplier_id']]['legal_name'],basis=['Catálogo ficticio seleccionado'],source_refs=[])],rotation=dict(message='Faltan salidas y stock medio del mismo período.'))
        for line in received_purchase_lines:
            group=metrics.get(line['article_id'],{}).get('suppliers',[])
            item=next((s for s in group if s['supplier_id']==line['supplier_id']),None)
            if item is None:
                item=dict(supplier_id=line['supplier_id'],name=line['supplier_name'],basis=[],source_refs=[]);group.append(item)
            if 'Línea recibida seleccionada' not in item['basis']:item['basis'].append('Línea recibida seleccionada')
            item['source_refs'].extend(line['source_refs'])
        sales=apply_links(self.db,self.store,dataset,documented_sales(self.store,dataset,info['as_of_date']))
        from eios.company_selected_sales import history_status
        with sqlite3.connect(self.db) as c:selected_sales_history,received_sales_lines=history_status(c,dataset)
        from eios.company_sales_catalogue import expanded_catalogue
        sales_catalogue=expanded_catalogue(dataset,articles,sales)
        result=dict(selected_sales_history=selected_sales_history,received_sales_lines=received_sales_lines,selected_purchase_history=selected_purchase_history,received_purchase_lines=received_purchase_lines,selected_inventory=selected_inventory,commercial_catalogue=commercial_catalogue,sales_catalogue=sales_catalogue,sales_proposals=offers(self.db,dataset),info=info, documentary_context=documentary_context, purchase_documents=documented_purchases(self.store,dataset,info['as_of_date']), sales=sales, customers=[r['data'] for r in self.store.records(dataset, 'customer')], suppliers=suppliers,
                    articles=articles,
                    pending=[r['data'] for r in self.store.records(dataset, 'missing_or_conflicting')],
                    purchases=proposals, inventory=read_inventory(self.db, dataset),
                    stock_minimums=minimums,
                    planning=planning_context(self.db, dataset, info['company']['company_id'], self.store.records(dataset, 'article')),
                    history=history, stock_metrics=metrics)
        from eios.company_data_status import describe_status
        result['data_status']=describe_status(self.db,result)
        return result

    def save(self, data):
        dataset = str(data['dataset_id'])
        state = self.state(dataset)
        supplier = str(data['supplier_id'])
        article = next((a for a in state['articles'] if a['article_id'] == data['article_id']), None)
        if supplier not in {s['supplier_id'] for s in state['suppliers']} or not article or article['supplier_id'] != supplier:
            raise ValueError('El artículo debe pertenecer al proveedor seleccionado.')
        from eios.company_commercial_terms import commercial_terms
        amounts = commercial_terms(data)
        reference = str(data.get('reference', '')).strip()
        if not reference or len(reference) > 100:
            raise ValueError('Indica una referencia de hasta 100 caracteres.')
        minimum=state['stock_minimums'][article['article_id']]
        expected=data.get('stock_minimum_revision')
        if expected is not None and (type(expected) is not int or expected!=minimum['revision']):
            raise ValueError('El mínimo del artículo ha cambiado. Recarga la pantalla antes de guardar la propuesta.')
        supplier_record = next(s for s in state['suppliers'] if s['supplier_id'] == supplier)
        supplier_snapshot = supplier_details(supplier_record)
        delivery = data.get('delivery_location', supplier_snapshot['delivery_location'])
        if delivery is not None and not isinstance(delivery, str):
            raise ValueError('El lugar de entrega debe ser texto.')
        delivery = delivery.strip() if delivery else None
        if delivery is not None and len(delivery) > 500:
            raise ValueError('El lugar de entrega admite hasta 500 caracteres.')
        result = dict(amounts, supplier_commercial_at_save=supplier_snapshot, delivery_location=delivery, proposal_id=str(uuid4()), dataset_id=dataset, reference=reference,
                      supplier_id=supplier, article_id=article['article_id'], unit=article['unit_as_documented'],
                      currency='EUR', status='PENDIENTE_DE_EVALUACION', decision_authority=False, operational_path='FORBIDDEN',
                      created_at=datetime.now(timezone.utc).isoformat())
        from eios.company_payment_plan import payment_plan
        result['payment_plan'] = payment_plan(data, result)
        from eios.company_required_calendar import document_references
        result['operation_document_references'] = document_references(data)
        result['stock_context_at_save']=dict(schema='COMPANY-PROPOSAL-STOCK-SNAPSHOT-01',
            captured_at=result['created_at'],documentary_cutoff=state['info']['as_of_date'],
            minimum=minimum,inventory=state['inventory'].get(article['article_id']),
            scope='DATED_REFERENCE_ONLY',decision_authority=False)
        with sqlite3.connect(self.db) as c:
            c.execute('PRAGMA foreign_keys=ON')
            c.execute('BEGIN IMMEDIATE')
            context = capture_context(c, dataset)
            expected_context = data.get('documentary_context_fingerprint', state['documentary_context']['fingerprint'])
            if context != state['documentary_context'] or expected_context != context['fingerprint']:
                raise ValueError('La versión documental ha cambiado. Recarga antes de guardar.')
            result['documentary_context_at_save'] = context
            if c.execute('SELECT 1 FROM manual_purchase_proposal WHERE dataset_id=? AND json_extract(payload,?)=?',
                         (dataset, '$.reference', reference)).fetchone():
                raise ValueError('Esta referencia ya está registrada en esta versión de empresa.')
            c.execute('INSERT INTO manual_purchase_proposal VALUES(?,?,?,?)',
                      (result['proposal_id'], dataset, result['created_at'], json.dumps(result)))
        return result


