def main():
    parser = argparse.ArgumentParser(description='EIOS: empresa y entrada local de propuestas de compra')
    parser.add_argument('--db', type=Path, required=True)
    parser.add_argument('--port', type=int, default=8765)
    args = parser.parse_args()
    desk = PurchaseDesk(args.db)
    token = secrets.token_urlsafe(32)
    importer = PreparedCompanyImport(desk.store)
    reception = CompanyReception(args.db)
    from eios.company_commercial_catalogue import CommercialCatalogue
    commercial_catalogue = CommercialCatalogue(args.db)
    from eios.company_selected_inventory import InventorySelection
    inventory_selection = InventorySelection(args.db)
    from eios.company_selected_purchases import PurchaseHistorySelection
    purchase_history_selection = PurchaseHistorySelection(args.db)
    from eios.company_sales_receivables import SalesReceivables
    sales_receivables = SalesReceivables(args.db)
    from eios.company_selected_sales import SalesHistorySelection
    sales_history_selection = SalesHistorySelection(args.db)

    class Handler(BaseHTTPRequestHandler):
        def send(self, status, data, html=False):
            body = data.encode() if html else json.dumps(data, ensure_ascii=False).encode()
            self.send_response(status)
            self.send_header('Content-Type', 'text/html; charset=utf-8' if html else 'application/json; charset=utf-8')
            self.send_header('Content-Length', str(len(body)))
            self.send_header('Cache-Control', 'no-store')
            self.send_header('X-Content-Type-Options', 'nosniff')
            self.end_headers()
            self.wfile.write(body)

        def do_GET(self):
            from urllib.parse import urlparse, parse_qs
            if self.headers.get('Host') not in {f'127.0.0.1:{args.port}', f'localhost:{args.port}'}:
                return self.send(403, dict(error='Host no permitido'))
            path = urlparse(self.path)
            try:
                if path.path == '/':
                    return self.send(200, PAGE.replace('TOKEN', json.dumps(token)), True)
                if path.path == '/api/reception/versions':
                    from eios.company_dossier_versions import versions
                    return self.send(200, versions(args.db))
                if path.path == '/api/reception/overviews':
                    from eios.company_dossier_overview import dossier_overviews
                    return self.send(200, dossier_overviews(args.db))
                if path.path == '/api/receptions':
                    return self.send(200, reception.batches())
                if path.path == '/api/datasets':
                    with sqlite3.connect(args.db) as c:
                        rows = c.execute('SELECT dataset_id,company_id,as_of_date FROM documentary_company_snapshot ORDER BY as_of_date DESC,dataset_id').fetchall()
                    return self.send(200, [dict(zip(('dataset_id','company_id','as_of_date'), r)) for r in rows])
                if path.path == '/api/parameters':
                    from eios.company_parameters import read_parameters
                    return self.send(200, read_parameters(args.db, desk.store, parse_qs(path.query)['dataset'][0]))
                if path.path == '/api/data-status':
                    return self.send(200,desk.state(parse_qs(path.query)['dataset'][0])['data_status'])
                if path.path == '/api/state':
                    return self.send(200, desk.state(parse_qs(path.query)['dataset'][0]))
                self.send(404, dict(error='No encontrado'))
            except (KeyError, ValueError):
                self.send(400, dict(error='Versión documental no válida'))

        def do_POST(self):
            if self.headers.get('Host') not in {f'127.0.0.1:{args.port}', f'localhost:{args.port}'}:
                return self.send(403, dict(error='Host no permitido'))
            if self.headers.get('X-EIOS-Token') != token:
                return self.send(403, dict(error='Sesión no válida. Recarga la pantalla.'))
            if self.path not in {'/api/reception/issues/export','/api/sales-history/preview','/api/sales-history/commit','/api/sales-history/clear','/api/reception/sales-reconcile','/api/reception/sales-collections/export','/api/purchase-history/preview','/api/purchase-history/commit','/api/purchase-history/clear','/api/inventory/preview','/api/inventory/commit','/api/inventory/clear','/api/catalogue/preview','/api/catalogue/commit','/api/catalogue/clear','/api/sales-proposals/tariff/template', '/api/sales-proposals/tariff', '/api/sales-proposals/link', '/api/sales-proposals/cash-plan', '/api/sales-proposals/cash-plan/read', '/api/sales-proposals', '/api/sales-proposals/preview', '/api/sales-proposals/context', '/api/sales-proposals/report', '/api/purchases/reviewer-designation/observation', '/api/purchases/reviewer-designation', '/api/purchases/treasury/observation', '/api/purchases/treasury/context', '/api/purchases/treasury/support', '/api/purchases/finance-quality/prepare', '/api/purchases/payments/calendar', '/api/purchases/payments/review', '/api/purchases/payments/document', '/api/purchases/payments/associate', '/api/parameters/finance/activate', '/api/parameters', '/api/stock/minimums', '/api/purchases', '/api/purchases/quote', '/api/purchases/review', '/api/purchases/report', '/api/purchases/commercial-draft', '/api/import/preview', '/api/import/commit', '/api/reception/read', '/api/reception/preview', '/api/reception/commit', '/api/reception/check', '/api/reception/original', '/api/reception/articles', '/api/reception/financials', '/api/reception/versions/save', '/api/reception/version', '/api/reception/version/export', '/api/reception/versions/compare', '/api/reception/records', '/api/reception/purchase/options', '/api/reception/purchase/prepare'}:
                return self.send(404, dict(error='No encontrado'))
            try:
                size = int(self.headers.get('Content-Length', '0'))
                limit = 131072 if self.path == '/api/parameters' else MAX_UPLOAD_BYTES if self.path == '/api/import/preview' else MAX_BYTES if self.path in ('/api/reception/read','/api/catalogue/preview') else 16384
                if not 0 < size <= limit:
                    raise ValueError('Solicitud demasiado grande o vacía.')
                if self.path == '/api/catalogue/preview':
                    from urllib.parse import unquote
                    options=json.loads(unquote(self.headers.get('X-EIOS-Catalogue','{}')))
                    return self.send(200,commercial_catalogue.preview(self.rfile.read(size),unquote(self.headers.get('X-EIOS-Filename','')),options))
                if self.path == '/api/reception/read':
                    from urllib.parse import unquote
                    delimiter = self.headers.get('X-EIOS-Delimiter', 'auto')
                    return self.send(200, reception.read(self.rfile.read(size),
                        unquote(self.headers.get('X-EIOS-Filename', '')),
                        sheet=unquote(self.headers.get('X-EIOS-Sheet', '')) or None,
                        header_row=int(self.headers.get('X-EIOS-Header-Row', '1')),
                        encoding=self.headers.get('X-EIOS-Encoding', 'utf-8-sig'),
                        delimiter='\t' if delimiter == 'tab' else delimiter))
                if self.path == '/api/import/preview':
                    return self.send(200, importer.preview(self.rfile.read(size)))
                data = json.loads(self.rfile.read(size))
                if self.path == '/api/sales-history/preview':return self.send(200,sales_history_selection.preview(data))
                if self.path == '/api/sales-history/commit':return self.send(200,sales_history_selection.commit(data))
                if self.path == '/api/sales-history/clear':return self.send(200,sales_history_selection.clear(data))
                if self.path == '/api/reception/sales-reconcile':return self.send(200,sales_receivables.check(data))
                if self.path == '/api/reception/sales-collections/export':return self.send(200,sales_receivables.export(data))
                if self.path == '/api/purchase-history/preview':return self.send(200,purchase_history_selection.preview(data))
                if self.path == '/api/purchase-history/commit':return self.send(200,purchase_history_selection.commit(data))
                if self.path == '/api/purchase-history/clear':return self.send(200,purchase_history_selection.clear(data))
                if self.path == '/api/inventory/preview':return self.send(200,inventory_selection.preview(data))
                if self.path == '/api/inventory/commit':return self.send(200,inventory_selection.commit(data))
                if self.path == '/api/inventory/clear':return self.send(200,inventory_selection.clear(data))
                if self.path == '/api/catalogue/commit':return self.send(200,commercial_catalogue.commit(data))
                if self.path == '/api/catalogue/clear':return self.send(200,commercial_catalogue.clear(data))
                if self.path == '/api/reception/original':
                    from urllib.parse import quote
                    original = reception.original(data['company_id'], data['batch_id'])
                    body = original['content']
                    self.send_response(200)
                    self.send_header('Content-Type', 'application/octet-stream')
                    self.send_header('Content-Disposition', "attachment; filename=\"documento\"; filename*=UTF-8''" + quote(original['filename'], safe=''))
                    self.send_header('Content-Length', str(len(body)))
                    self.send_header('Cache-Control', 'no-store')
                    self.send_header('X-Content-Type-Options', 'nosniff')
                    self.send_header('X-EIOS-Source-SHA256', original['source_sha256'])
                    self.end_headers()
                    self.wfile.write(body)
                    return
                if self.path == '/api/reception/purchase/options':
                    from eios.company_purchase_preparation import preparation_options
                    return self.send(200, preparation_options(args.db, data['dossier_id']))
                if self.path == '/api/reception/purchase/prepare':
                    from eios.company_purchase_preparation import prepare_purchase
                    return self.send(200, prepare_purchase(args.db, data['dossier_id'], data['operation']))
                if self.path == '/api/reception/records':
                    return self.send(200, reception.record_page(data['company_id'], data['batch_id'], data.get('offset', 0), data.get('limit', 50), data.get('query', '')))
                if self.path == '/api/reception/versions/compare':
                    from eios.company_dossier_comparison import compare_versions
                    return self.send(200, compare_versions(args.db, data['before_id'], data['after_id']))
                if self.path == '/api/reception/version/export':
                    from eios.company_dossier_export import export_version
                    exported = export_version(args.db, data['dossier_id'])
                    body = exported['content']
                    self.send_response(200)
                    self.send_header('Content-Type', 'application/zip')
                    self.send_header('Content-Disposition', 'attachment; filename="' + exported['filename'] + '"')
                    self.send_header('Content-Length', str(len(body)))
                    self.send_header('Cache-Control', 'no-store')
                    self.send_header('X-Content-Type-Options', 'nosniff')
                    self.end_headers()
                    self.wfile.write(body)
                    return
                if self.path == '/api/reception/versions/save':
                    from eios.company_dossier_versions import save_version
                    return self.send(200, save_version(args.db, data['batch_ids'], data['name']))
                if self.path == '/api/reception/version':
                    from eios.company_dossier_versions import version
                    return self.send(200, version(args.db, data['dossier_id']))
                if self.path == '/api/reception/financials':
                    from eios.company_received_financials import received_financials
                    return self.send(200, received_financials(args.db, data['batch_ids']))
                if self.path == '/api/reception/articles':
                    from eios.company_received_articles import received_article
                    return self.send(200, received_article(args.db, data['batch_ids'], data.get('article_id')))
                if self.path == '/api/reception/check':
                    from eios.company_dossier import check_dossier
                    return self.send(200, check_dossier(args.db, data['batch_ids']))
                if self.path == '/api/reception/issues/export':
                    return self.send(200,reception.issues(data))
                if self.path == '/api/reception/preview':
                    return self.send(200, reception.preview(data))
                if self.path == '/api/reception/commit':
                    return self.send(200, reception.commit(data['ticket']))
                if self.path == '/api/import/commit':
                    return self.send(200, importer.commit(data['ticket']))
                if self.path == '/api/parameters/finance/activate':
                    from eios.company_finance_parameters import activate_finance_parameters
                    return self.send(200, activate_finance_parameters(args.db,desk.store,data))
                if self.path == '/api/parameters':
                    from eios.company_parameters import save_parameters
                    return self.send(200, save_parameters(args.db, desk.store, data))
                if self.path == '/api/stock/minimums':
                    return self.send(200, save_minimums(desk.db, desk.store, data))
                if self.path == '/api/purchases/quote':
                    from eios.company_commercial_terms import commercial_terms
                    return self.send(200, commercial_terms(data))
                if self.path == '/api/purchases/commercial-draft':
                    return self.send(200, desk.commercial_draft(str(data['dataset_id']), str(data['proposal_id']), str(data['review_id'])))
                if self.path == '/api/purchases/report':
                    return self.send(200, desk.printable_report(str(data['dataset_id']), str(data['proposal_id']), str(data['review_id'])), html=True)
                if self.path in ('/api/sales-proposals/cash-plan','/api/sales-proposals/cash-plan/read'):
                    return self.send(200,desk.sales_cash_plan(data,save=self.path=='/api/sales-proposals/cash-plan'))
                if self.path == '/api/sales-proposals/report':
                    from eios.company_sales_proposals import printable_offer
                    return self.send(200,dict(html=printable_offer(desk.db,str(data['dataset_id']),str(data['proposal_id']))))
                if self.path == '/api/sales-proposals/tariff/template':
                    import base64
                    from eios.company_sales_tariff_template import build_template
                    template=build_template(desk.state(str(data['dataset_id'])))
                    return self.send(200,dict(filename=template['filename'],article_count=template['article_count'],content_base64=base64.b64encode(template['content']).decode('ascii')))
                if self.path == '/api/sales-proposals/tariff':
                    from eios.company_sales_tariffs import save_tariff
                    return self.send(200,save_tariff(desk.db,data))
                if self.path == '/api/sales-proposals/link':
                    from eios.company_sales_links import save_link
                    return self.send(200,save_link(desk.db,desk.store,data))
                if self.path == '/api/sales-proposals/context':
                    return self.send(200,desk.sales_orientation(data))
                if self.path in ('/api/sales-proposals','/api/sales-proposals/preview'):
                    return self.send(200,desk.sales_offer(data,persist=self.path=='/api/sales-proposals'))
                if self.path == '/api/purchases/reviewer-designation/observation':
                    return self.send(200,desk.record_designation_observation(data))
                if self.path == '/api/purchases/reviewer-designation':
                    return self.send(200,desk.record_reviewer_designation(data))
                if self.path == '/api/purchases/treasury/observation':
                    return self.send(200,desk.record_treasury_observation(data))
                if self.path == '/api/purchases/treasury/context':
                    return self.send(200,desk.record_treasury_context(data))
                if self.path == '/api/purchases/treasury/support':
                    return self.send(200,desk.record_treasury_support(data))
                if self.path == '/api/purchases/finance-quality/prepare':
                    return self.send(200,desk.prepare_finance_quality(data))
                if self.path == '/api/purchases/payments/calendar':
                    return self.send(200,desk.record_required_calendar(data))
                if self.path == '/api/purchases/payments/review':
                    return self.send(200,desk.record_payment_documentary_review(data))
                if self.path == '/api/purchases/payments/document':
                    from urllib.parse import quote
                    original=desk.captured_payment_document(str(data['dataset_id']),str(data['proposal_id']),
                        str(data['review_id']),data['document_ref'])
                    body=original['content']
                    self.send_response(200)
                    self.send_header('Content-Type','application/octet-stream')
                    self.send_header('Content-Disposition',"attachment; filename=\"soporte\"; filename*=UTF-8''"+quote(original['filename'],safe=''))
                    self.send_header('Content-Length',str(len(body)))
                    self.send_header('Cache-Control','no-store')
                    self.send_header('X-Content-Type-Options','nosniff')
                    self.send_header('X-EIOS-Filename',quote(original['filename'],safe=''))
                    self.send_header('X-EIOS-Source-SHA256',original['source_sha256'])
                    self.end_headers()
                    self.wfile.write(body)
                    return
                if self.path == '/api/purchases/payments/associate':
                    return self.send(200, desk.declare_payment_association(data))
                if self.path == '/api/purchases/review':
                    return self.send(200, desk.review(str(data['dataset_id']), str(data['proposal_id'])))
                self.send(201, desk.save(data))
            except (ValueError, KeyError, TypeError) as error:
                self.send(400, dict(error=str(error)))

    server = HTTPServer(('127.0.0.1', args.port), Handler)
    print(f'EIOS: abre http://127.0.0.1:{args.port} · Ctrl+C para cerrar', flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == '__main__':
    main()
